use verus::prelude::*;

verus! {

    /// Transpose a non‐empty rectangular matrix of 8‐bit signed integers.
    ///
    /// Given an m×n matrix `arr` (with m = arr.len(), n = arr[0].len()),
    /// returns an n×m matrix `result` such that
    /// for all 0 ≤ i < m and 0 ≤ j < n, result[j][i] == arr[i][j].
    fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>>
        requires(arr.len() > 0)
        requires(forall(|i: int| 0 <= i && i < arr.len() ==>
            arr[i].len() == arr[0].len()))
        ensures(|result: Vec<Vec<i8>>|
            // the new number of rows equals the original number of columns
            result.len() == arr[0].len()
            // each new row has length equal to the original number of rows
            && forall(|j: int| 0 <= j && j < result.len() ==>
                result[j].len() == arr.len())
            // the transpose property
            && forall(|i: int, j: int|
                0 <= i && i < arr.len() &&
                0 <= j && j < arr[0].len() ==>
                    result[j][i] == arr[i][j]
            )
        )
    {
        let m = arr.len();
        let n = arr[0].len();

        // build the result row by row (i.e., column by column of the original)
        let mut res: Vec<Vec<i8>> = Vec::new();
        let mut j: int = 0;
        while j < n {
            invariant(0 <= j && j <= n);
            invariant(res.len() == j);
            // for all completed rows jj < j, we have res[jj][ii] == arr[ii][jj]
            invariant(forall(|jj: int, ii: int|
                0 <= jj && jj < j &&
                0 <= ii && ii < m ==>
                    res[jj][ii] == arr[ii][jj]
            ));
            decreases(n - j);

            // build the j-th row of the result
            let mut row: Vec<i8> = Vec::new();
            let mut i: int = 0;
            while i < m {
                invariant(0 <= i && i <= m);
                invariant(row.len() == i);
                // for all completed elements ii < i, row[ii] == arr[ii][j]
                invariant(forall(|ii: int|
                    0 <= ii && ii < i ==>
                        row[ii] == arr[ii][j]
                ));
                decreases(m - i);

                row.push(arr[i][j]);
                i += 1;
            }

            res.push(row);
            j += 1;
        }

        res
    }

}